alter table public.journal_entries add constraint journal_complete_content CHECK (((content ?& ARRAY['id'::text, 'title'::text, 'matchDate'::text, 'opponent'::text, 'score'::text, 'mood'::text, 'motm'::text, 'body'::text, 'moment'::text, 'image'::text, 'createdAt'::text, 'updatedAt'::text]) AND ((content - ARRAY['id'::text, 'title'::text, 'matchDate'::text, 'opponent'::text, 'score'::text, 'mood'::text, 'motm'::text, 'body'::text, 'moment'::text, 'image'::text, 'createdAt'::text, 'updatedAt'::text]) = '{}'::jsonb) AND (jsonb_typeof((content -> 'matchDate'::text)) = 'string'::text) AND (to_char((((content ->> 'matchDate'::text))::date)::timestamp with time zone, 'YYYY-MM-DD'::text) = (content ->> 'matchDate'::text)) AND (jsonb_typeof((content -> 'score'::text)) = 'string'::text) AND (length((content ->> 'score'::text)) <= 25) AND (jsonb_typeof((content -> 'mood'::text)) = 'string'::text) AND ((content ->> 'mood'::text) = ANY (ARRAY[''::text, 'มีความสุข'::text, 'ภูมิใจ'::text, 'ลุ้นสุดใจ'::text, 'เสียดาย'::text, 'ยังเชียร์เสมอ'::text])) AND (jsonb_typeof((content -> 'motm'::text)) = 'string'::text) AND (length((content ->> 'motm'::text)) <= 100) AND (jsonb_typeof((content -> 'moment'::text)) = 'string'::text) AND (length((content ->> 'moment'::text)) <= 1000) AND (jsonb_typeof((content -> 'image'::text)) = 'string'::text) AND (jsonb_typeof((content -> 'createdAt'::text)) = 'string'::text) AND (length((content ->> 'createdAt'::text)) <= 40) AND (jsonb_typeof((content -> 'updatedAt'::text)) = 'string'::text) AND (length((content ->> 'updatedAt'::text)) <= 40)));
